ALTER TABLE public.direct_messages ADD COLUMN file_path text, ADD COLUMN file_name text;
ALTER TABLE public.direct_messages ADD CONSTRAINT direct_attachment_pair CHECK ((file_path IS NULL AND file_name IS NULL) OR (file_path IS NOT NULL AND file_name IS NOT NULL AND length(file_name) BETWEEN 1 AND 255 AND length(file_path) < 600));
REVOKE INSERT ON public.direct_messages FROM authenticated;
CREATE POLICY "Thread participants read direct attachments" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'direct-attachments' AND EXISTS (SELECT 1 FROM public.direct_threads t WHERE t.id::text = (storage.foldername(name))[2] AND (t.buyer_id = auth.uid() OR t.seller_id = auth.uid())));
CREATE POLICY "Participants upload own direct attachments" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'direct-attachments' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.direct_threads t WHERE t.id::text = (storage.foldername(name))[2] AND (t.buyer_id = auth.uid() OR t.seller_id = auth.uid())) AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.blocked));
CREATE POLICY "Owners remove unsent direct attachments" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'direct-attachments' AND (storage.foldername(name))[1] = auth.uid()::text AND NOT EXISTS (SELECT 1 FROM public.direct_messages m WHERE m.file_path = name));